162	// sameCommitResult は、起点とレビューした内容が同じコミットのときの結果を返す。レビューした内容の
163	// どの行も、起点の同じ行番号の行である。行がレビューした内容の行数を越えるのは、git blame を実行する
164	// ときと同じく入力の誤りにする。
165	func sameCommitResult(g gitRunner, base, target string, opts options) (result, error) {
166		n, err := g.lineCount(target, opts)
167		if err != nil {
168			return result{}, err
169		}
170		if err := checkLastLine(opts, n); err != nil {
171			return result{}, err
172		}
173		res := result{kind: holds, reason: fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))}
174		for _, r := range opts.ranges {
175			for line := r.from; line <= r.to; line++ {
176				res.lines = append(res.lines, lineResult{line: line, kind: holds, note: fmt.Sprintf("全量の起点にあったまま (起点の %d 行目)", line)})
177			}
178		}
179		return res, nil
180	}
