182	// checkLastLine は、渡した行がレビューした内容の行数 n を越えないかを確認する。越えるのは渡し方の誤り。
183	func checkLastLine(opts options, n int) error {
184		if last := opts.ranges[len(opts.ranges)-1].to; last > n {
185			return inputf("行 %d が、レビューした内容の -file の行数 (%d) を越えます", last, n)
186		}
187		return nil
188	}
