190	// classify は blame の結果を行ごとに分類し、全体の結果を決める。
191	// 成り立たない行が 1 つでもあれば成り立たない、無くて確認できない行があれば確認できない。
192	func classify(base, file string, blamed []blameLine) result {
193		res := result{kind: holds}
194		for _, b := range blamed {
195			l := lineResult{line: b.final}
196			switch {
197			case isZero(b.commit):
198				l.kind, l.note = notHolds, "コミットしていない行"
199			case !b.boundary:
200				l.kind, l.note = notHolds, fmt.Sprintf("全量の起点より後のコミット %s が書いた・書き換えた行", short(b.commit))
201			case b.commit != base:
202				// 起点より前に分かれた履歴をマージすると、行がその分岐点まで遡り、そこが境界になる。
203				// その行が起点にもあったかは、この結果からは決められない。
204				l.kind, l.note = unverifiable, fmt.Sprintf("全量の起点を通らない履歴 (起点より前に分かれた履歴のマージなど) から来た行で、境界のコミットが %s。全量の起点にあったかを決められない", short(b.commit))
205			case b.filename != file:
206				l.kind, l.note = notHolds, fmt.Sprintf("このブランチで改名・移動したファイルの行 (全量の起点では %s)", b.filename)
207			default:
208				// 境界が起点でパスも同じなので、フィールド orig は起点のファイルでの行番号
209				l.kind, l.note = holds, fmt.Sprintf("全量の起点にあったまま (起点の %d 行目)", b.orig)
210			}
211			res.lines = append(res.lines, l)
212			switch {
213			case l.kind == notHolds:
214				res.kind = notHolds
215			case l.kind == unverifiable && res.kind == holds:
216				res.kind = unverifiable
217			}
218		}
219		switch res.kind {
220		case notHolds:
221			res.reason = "対象の行のうち、全量の起点から変わった行がある"
222		case unverifiable:
223			res.reason = "対象の行のうち、全量の起点にあったかを決められない行がある"
224		default:
225			res.reason = fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))
226		}
227		return res
228	}
