230	// lineCount は、レビューした内容の -file の行数を返す。数え方は git blame と同じで、
231	// 末尾に改行の無い最後の行も 1 行と数える。
232	func (g gitRunner) lineCount(target string, opts options) (int, error) {
233		var content []byte
234		if opts.worktree {
235			b, err := os.ReadFile(filepath.Join(g.root, filepath.FromSlash(opts.file)))
236			if err != nil {
237				return 0, runf("作業ツリーの -file を読めません: %v", err)
238			}
239			content = b
240		} else {
241			out, _, err := g.run("cat-file", "-p", target+":"+opts.file)
242			if err != nil {
243				return 0, asRun(err)
244			}
245			content = []byte(out)
246		}
247		n := bytes.Count(content, []byte("\n"))
248		if len(content) > 0 && content[len(content)-1] != '\n' {
249			n++
250		}
251		return n, nil
252	}
