264	// parsePorcelain は git blame --line-porcelain の出力を読む。
265	func parsePorcelain(out string) ([]blameLine, error) {
266		var lines []blameLine
267		var cur *blameLine
268		for _, s := range strings.Split(out, "\n") {
269			if cur == nil {
270				if s == "" {
271					continue
272				}
273				m := blameHeader.FindStringSubmatch(s)
274				if m == nil {
275					return nil, fmt.Errorf("git blame の出力を読めません: %q", s)
276				}
277				orig, _ := strconv.Atoi(m[2])
278				final, _ := strconv.Atoi(m[3])
279				cur = &blameLine{orig: orig, final: final, commit: m[1]}
280				continue
281			}
282			switch {
283			case strings.HasPrefix(s, "\t"):
284				if cur.filename == "" {
285					return nil, fmt.Errorf("git blame の出力に行 %d のファイル名がありません", cur.final)
286				}
287				lines = append(lines, *cur)
288				cur = nil
289			case s == "boundary":
290				cur.boundary = true
291			case strings.HasPrefix(s, "filename "):
292				name, err := unquotePath(strings.TrimPrefix(s, "filename "))
293				if err != nil {
294					return nil, err
295				}
296				cur.filename = name
297			}
298		}
299		if cur != nil {
300			return nil, fmt.Errorf("git blame の出力が行 %d の途中で途切れています", cur.final)
301		}
302		return lines, nil
303	}
