305	// unquotePath は、git が引用符で囲んで出したパス (日本語や " を含むもの。例: "\346\227\245.md") を元に戻す。
306	func unquotePath(s string) (string, error) {
307		if !strings.HasPrefix(s, `"`) {
308			return s, nil
309		}
310		u, err := strconv.Unquote(s)
311		if err != nil {
312			return "", fmt.Errorf("git blame の出力のファイル名を読めません: %s", s)
313		}
314		return u, nil
315	}
