565	// (通常のファイルをシンボリックリンクに置き換えたなど)、ハッシュを比べずに変更ありとする。ハッシュだけを
566	// 比べると、リンクの文字列がファイルの内容とちょうど同じときに、同じ内容と見なしてしまう。
567	func (g gitRunner) hasUncommittedChange(top, rev, kind, file string) (bool, error) {
568		committed, err := g.blob(rev, file)
569		if err != nil {
570			return false, err
571		}
572		out, _, err := g.run("ls-files", "--stage", "--", file)
573		if err != nil {
574			return false, err
575		}
576		// 項目のどれかのステージが 0 でなければ、変更ありとする。衝突の解消の途中は、インデックスに同じパスの
577		// 項目がステージ 1〜3 に分かれてあるので、これに当たる。項目の種類 (mode) が kind と違うときも変更ありとする
578		var index string
579		if out != "" {
580			for _, e := range strings.Split(strings.TrimSpace(out), "\n") {
581				fields := strings.Fields(e)
582				if len(fields) < 3 || fields[2] != "0" || modeKind(fields[0]) != kind {
583					return true, nil
584				}
585				index = fields[1]
586			}
587		}
588		// 作業ツリーの内容のハッシュを、git が記録するのと同じ形で求める。git が記録するのは通常の
589		// ファイルとシンボリックリンクだけで、シンボリックリンクはリンクの先ではなくリンクの文字列を記録する
590		var worktree string
591		abs := filepath.Join(top, filepath.FromSlash(file))
592		st, err := os.Lstat(abs)
593		switch {
594		case os.IsNotExist(err):
595			// 作業ツリーから消した。worktree は空のまま
596		case err != nil:
597			return false, runf("作業ツリーの -file を読めません: %v", err)
598		case st.Mode().IsRegular():
599			if kind != entryFile {
600				return true, nil
601			}
602			// --path で、そのパスの属性によるフィルタ (改行の変換など) を当ててからハッシュを求める。オプション -w を付けないので書き込まない
603			out, _, err := g.run("hash-object", "--path="+file, "--", abs)
604			if err != nil {
605				return false, err
606			}
607			worktree = strings.TrimSpace(out)
608		case st.Mode()&os.ModeSymlink != 0:
609			if kind != entrySymlink {
610				return true, nil
611			}
612			link, err := os.Readlink(abs)
613			if err != nil {
614				return false, runf("作業ツリーの -file のリンクを読めません: %v", err)
615			}
616			out, _, err := g.runIn(strings.NewReader(link), "hash-object", "--no-filters", "--stdin")
617			if err != nil {
618				return false, err
619			}
620			worktree = strings.TrimSpace(out)
621		default:
622			// ディレクトリなど、git が記録しない種類に置き換わっている
623			return true, nil
624		}
625		return committed != index || index != worktree, nil
626	}
