628	// convertingAttribute は、file に、レビュアが読む内容と git が比べる内容を違えうる属性が設定されて
629	// いれば、その名前 (filter か ident) を返す。無ければ空を返す。両方あれば filter を返す。
630	//
631	// 属性 filter (コマンド git add のときにファイルを変換するプログラム) の値はドライバ (設定
632	// filter.<名前>.clean などで登録する、変換のプログラムの名前) で、設定の無いドライバの名前や、値の無い
633	// filter も「あり」とする。
634	// 属性 ident (ファイルの中の「$Id$」を、取り出すときにブロブの SHA を入れた「$Id: … $」に展開し、記録する
635	// ときに「$Id$」へ戻す仕組み) は、unset 以外の値なら「あり」とする (git が展開するのは値が set のときだけ)。
636	// 「あり」なら呼び出し元は確認せずに unverifiable を返すので、迷う場合を「あり」として扱っても、
637	// 誤った holds にはならない。
638	func (g gitRunner) convertingAttribute(file string) (string, error) {
639		// オプション -a は、値のある属性 (unset を含む) だけを出し、属性が無い (unspecified) ものは出さない。
640		// filter だけを問い合わせると、属性が無いことと、名前が unspecified のドライバを同じ出力で返す
641		out, _, err := g.run("check-attr", "-a", "-z", "--", file)
642		if err != nil {
643			return "", asRun(err)
644		}
645		// オプション -z の出力は「<パス> NUL <属性> NUL <値> NUL」の繰り返しで、属性が無ければ空。NUL で分けると、
646		// 要素の数は 3 の倍数に 1 を足した数になり、最後は空になる。そうでない出力は読めないので run-error にする
647		// (読めない出力を属性無しとして扱い、git blame で行を調べに進むと、誤った holds になりうる)
648		parts := strings.Split(out, "\x00")
649		if len(parts)%3 != 1 || parts[len(parts)-1] != "" {
650			return "", runf("git check-attr の出力を読めません: %q", out)
651		}
652		ident := false
653		for k := 0; k+2 < len(parts); k += 3 {
654			switch parts[k+1] {
655			case "filter":
656				if parts[k+2] != "unset" {
657					return "filter", nil
658				}
659				// unset は、-filter (フィルタを外す) と、名前が unset のドライバを区別できないので、
660				// そのドライバの設定があれば「あり」とする
661				_, code, err := g.run("config", "--get-regexp", `^filter\.unset\.(clean|process)$`)
662				switch code {
663				case 0:
664					return "filter", nil
665				case 1:
666					// ドライバの設定が無いので、-filter (フィルタを外す)
667				default:
668					return "", asRun(err)
669				}
670			case "ident":
671				ident = parts[k+2] != "unset"
672			}
673		}
674		if ident {
675			return "ident", nil
676		}
677		return "", nil
678	}
